CREATE TABLE [dbo].[cstoprovedor](	  [provedor_id] SMALLINT NOT NULL IDENTITY(1,1)	, [descrip] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [prefix] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [codigoCarrierBR] VARCHAR(5) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, CONSTRAINT [PK_cstoProvedor] PRIMARY KEY ([provedor_id] ASC))